import { join } from 'path';

/** Directorio raíz desde el que se arranca la aplicación. */
export const PROJECT_ROOT = process.cwd();

export const PUBLIC_DIR = join(PROJECT_ROOT, 'public');
export const VIEWS_DIR = join(PROJECT_ROOT, 'views');

export const POSTS_IMAGE_DIR = join(PUBLIC_DIR, 'images', 'blog');
export const GALLERY_IMAGE_DIR = join(PUBLIC_DIR, 'images', 'index', 'gallery');
export const PORTFOLIO_IMAGE_DIR = join(
  PUBLIC_DIR,
  'images',
  'index',
  'portfolio',
);

/**
 * Genera un slug equivalente al AsciiSlugger de Symfony:
 * quita acentos, pasa a minúsculas y sustituye cualquier grupo de
 * caracteres no alfanuméricos por un guion.
 */
export function slugify(value: string): string {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

const MONTHS = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];

/**
 * Implementa los formatos de fecha de Twig que usan las plantillas
 * del proyecto original (`d F`, `g:i A`, `h:i A`, etc.).
 */
export function formatDate(value: Date | string, format = 'd F Y'): string {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    return '';
  }

  const hours = date.getHours();
  const hours12 = hours % 12 || 12;

  const replacements: Record<string, string> = {
    d: String(date.getDate()).padStart(2, '0'),
    j: String(date.getDate()),
    F: MONTHS[date.getMonth()],
    M: MONTHS[date.getMonth()].slice(0, 3),
    m: String(date.getMonth() + 1).padStart(2, '0'),
    n: String(date.getMonth() + 1),
    Y: String(date.getFullYear()),
    y: String(date.getFullYear()).slice(-2),
    g: String(hours12),
    h: String(hours12).padStart(2, '0'),
    G: String(hours),
    H: String(hours).padStart(2, '0'),
    i: String(date.getMinutes()).padStart(2, '0'),
    s: String(date.getSeconds()).padStart(2, '0'),
    A: hours < 12 ? 'AM' : 'PM',
    a: hours < 12 ? 'am' : 'pm',
  };

  return format.replace(/\\.|[a-zA-Z]/g, (token) => {
    if (token.startsWith('\\')) {
      return token.slice(1);
    }
    return replacements[token] ?? token;
  });
}

/** Equivalente al helper `asset()` de Twig. */
export function asset(path: string): string {
  return `/${String(path ?? '').replace(/^\/+/, '')}`;
}

/** Normaliza un valor de formulario a string. */
export function formString(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

export function isEmail(value: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

export function parseInteger(value: unknown, fallback: number): number {
  const raw = formString(value);
  if (raw === '') {
    return fallback;
  }
  const parsed = Number(raw);
  return Number.isInteger(parsed) ? parsed : Number.NaN;
}

export type PagerPage = {
  label: string;
  url?: string;
  active?: boolean;
  gap?: boolean;
};

export type Pager = {
  previousUrl?: string;
  nextUrl?: string;
  pages: PagerPage[];
  status: string;
};

/**
 * Construye los datos que consume `partials/pagination.njk`.
 * `mode` es "path" para /blog/2 o "query" para ?page=2.
 */
export function buildPager(
  basePath: string,
  page: number,
  totalPages: number,
  query: Record<string, string> = {},
  mode: 'path' | 'query' = 'path',
  windowSize = 2,
): Pager | null {
  if (totalPages <= 1) {
    return null;
  }

  const urlFor = (target: number): string => {
    if (mode === 'path') {
      return `${basePath}/${target}`;
    }
    const params = new URLSearchParams({ ...query, page: String(target) });
    return `${basePath}?${params.toString()}`;
  };

  const from = Math.max(1, page - windowSize);
  const to = Math.min(totalPages, page + windowSize);
  const pages: PagerPage[] = [];

  if (from > 1) {
    pages.push({ label: '1', url: urlFor(1) });
    if (from > 2) {
      pages.push({ label: '…', gap: true });
    }
  }

  for (let i = from; i <= to; i += 1) {
    pages.push({ label: String(i), url: urlFor(i), active: i === page });
  }

  if (to < totalPages) {
    if (to < totalPages - 1) {
      pages.push({ label: '…', gap: true });
    }
    pages.push({ label: String(totalPages), url: urlFor(totalPages) });
  }

  return {
    previousUrl: page > 1 ? urlFor(page - 1) : undefined,
    nextUrl: page < totalPages ? urlFor(page + 1) : undefined,
    pages,
    status: `Página ${page} de ${totalPages}`,
  };
}

import { ForbiddenException, Injectable } from '@nestjs/common';
import { randomBytes } from 'crypto';
import { Request } from 'express';

@Injectable()
export class CsrfService {
  token(req: Request): string {
    if (!req.session.csrfToken) {
      req.session.csrfToken = randomBytes(32).toString('hex');
    }
    return req.session.csrfToken;
  }

  /**
   * Symfony usa `_token` en los formularios y `_csrf_token` en el login.
   * Aceptamos ambos nombres, además de `_csrf`.
   */
  assertValid(req: Request): void {
    const body = (req.body ?? {}) as Record<string, unknown>;
    const sent = body._csrf ?? body._token ?? body._csrf_token;
    if (
      typeof sent !== 'string' ||
      !req.session?.csrfToken ||
      sent !== req.session.csrfToken
    ) {
      throw new ForbiddenException('Token CSRF inválido o expirado.');
    }
  }
}

