import { Injectable, NestMiddleware } from '@nestjs/common';
import { NextFunction, Request, Response } from 'express';
import { UsersService } from '../users/users.service';
import { CsrfService } from './csrf.service';

@Injectable()
export class AppViewMiddleware implements NestMiddleware {
  constructor(
    private readonly usersService: UsersService,
    private readonly csrfService: CsrfService,
  ) {}

  async use(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      res.locals.currentPath = req.path;
      res.locals.currentUser = null;

      if (req.session) {
        res.locals.flash = req.session.flash ?? null;
        delete req.session.flash;

        res.locals.csrfToken = this.csrfService.token(req);

        if (req.session.userId) {
          const user = await this.usersService.findById(req.session.userId);
          if (user) {
            req.user = user;
            res.locals.currentUser = user;
          } else {
            delete req.session.userId;
          }
        }
      }

      next();
    } catch (error) {
      next(error);
    }
  }
}

import {
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Injectable,
} from '@nestjs/common';
import { Request, Response } from 'express';

/** Exige que haya una sesión iniciada; si no, redirige a /login. */
@Injectable()
export class AuthGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const req = context.switchToHttp().getRequest<Request>();
    const res = context.switchToHttp().getResponse<Response>();

    if (req.user) {
      return true;
    }

    res.redirect('/login');
    return false;
  }
}

/** Equivale a `access_control: { path: ^/admin, roles: ROLE_ADMIN }`. */
@Injectable()
export class AdminGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const req = context.switchToHttp().getRequest<Request>();
    const res = context.switchToHttp().getResponse<Response>();

    if (!req.user) {
      res.redirect('/login');
      return false;
    }

    if (!req.user.isAdmin) {
      throw new ForbiddenException('No tienes permisos de administrador.');
    }

    return true;
  }
}

import { diskStorage } from 'multer';
import { randomBytes } from 'crypto';
import { extname } from 'path';
import { unlink } from 'fs/promises';
import { slugify } from './slug';

export const ALLOWED_IMAGE_TYPES: Record<string, string> = {
  'image/jpeg': 'jpg',
  'image/jpg': 'jpg',
  'image/png': 'png',
};

export function isAllowedImageMime(mimetype: string): boolean {
  return Boolean(ALLOWED_IMAGE_TYPES[mimetype]);
}

/**
 * Guarda la imagen con un nombre parecido al que generaba Symfony:
 * `<slug-del-nombre>-<identificador-unico>.<extension>`
 */
export function imageStorage(destination: string) {
  return diskStorage({
    destination,
    filename: (_req, file, callback) => {
      const originalWithoutExtension = file.originalname.replace(/\.[^.]+$/, '');
      const base = slugify(originalWithoutExtension) || 'imagen';
      const extension =
        ALLOWED_IMAGE_TYPES[file.mimetype] ||
        extname(file.originalname).replace('.', '') ||
        'jpg';
      const unique = `${Date.now().toString(16)}${randomBytes(4).toString('hex')}`;
      callback(null, `${base}-${unique}.${extension}`);
    },
  });
}

export async function removeUploadedFile(
  file?: Express.Multer.File,
): Promise<void> {
  if (!file?.path) {
    return;
  }
  await unlink(file.path).catch(() => undefined);
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
