import { Request, Response } from 'express';
import { BlogService, POSTS_PER_PAGE } from './blog.service';
import { AuthGuard } from '../common/guards';
import { CsrfService } from '../common/csrf.service';
import { POSTS_IMAGE_DIR } from '../common/paths';
import {
  imageStorage,
  isAllowedImageMime,
  removeUploadedFile,
} from '../common/upload';
import {
  buildPager,
  formString,
  isEmail,
} from '../common/view-helpers';

@Controller()
export class BlogController {
  constructor(
    private readonly blogService: BlogService,
    private readonly csrfService: CsrfService,
  ) {}

  @Get('blog')
  blogRoot(@Res() res: Response): Promise<void> {
    return this.renderBlogPage(res, 1);
  }

  @Get('blog/new')
  @UseGuards(AuthGuard)
  newPostForm(@Res() res: Response): void {
    res.render('blog/new_post', {
      values: {},
      errors: {},
    });
  }

  @Post('blog/new')
  @UseGuards(AuthGuard)
  @UseInterceptors(
    FileInterceptor('image', {
      storage: imageStorage(POSTS_IMAGE_DIR),
      limits: { fileSize: 5 * 1024 * 1024 },
    }),
  )
  async createPost(
    @Req() req: Request,
    @Res() res: Response,
    @UploadedFile() file?: Express.Multer.File,
  ): Promise<void> {
    try {
      this.csrfService.assertValid(req);
    } catch (error) {
      await removeUploadedFile(file);
      throw error;
    }

    const values = {
      title: formString(req.body.title),
      content: formString(req.body.content),
    };

    const errors: Record<string, string> = {};
    if (!values.title) {
      errors.title = 'El título es obligatorio';
    }
    if (!values.content) {
      errors.content = 'El contenido es obligatorio';
    }
    if (!file) {
      errors.image = 'La imagen es obligatoria';
    } else if (!isAllowedImageMime(file.mimetype)) {
      errors.image = 'Por favor sube una imagen válida (JPEG o PNG)';
    }

    if (Object.keys(errors).length > 0) {
      await removeUploadedFile(file);
      res.render('blog/new_post', { values, errors });
      return;
    }

    const post = await this.blogService.createPost(
      { ...values, image: file.filename },
      req.user,
    );

    req.session.flash = {
      type: 'success',
      message: 'El post se ha publicado correctamente.',
    };
    res.redirect(`/single_post/${encodeURIComponent(post.slug)}`);
  }

  @Get('blog/buscar')
  async search(
    @Query('searchTerm') rawSearchTerm: string,
    @Res() res: Response,
  ): Promise<void> {
    const searchTerm = formString(rawSearchTerm);
    const [posts, recents] = await Promise.all([
      this.blogService.findByText(searchTerm),
      this.blogService.findRecents(),
    ]);

    res.render('blog/index', {
      posts,
      recents,
      searchTerm,
      pager: null,
    });
  }

  @Get('blog/:page')
  async blogPage(
    @Param('page') rawPage: string,
    @Res() res: Response,
  ): Promise<void> {
    if (!/^\d+$/.test(rawPage)) {
      throw new NotFoundException();
    }
    await this.renderBlogPage(res, Math.max(1, Number(rawPage)));
  }

  @Get('single_post/:slug')
  async singlePost(
    @Param('slug') slug: string,
    @Res() res: Response,
  ): Promise<void> {
    await this.renderSinglePost(res, slug);
  }

  @Post('single_post/:slug/comment')
  async addComment(
    @Param('slug') slug: string,
    @Req() req: Request,
    @Res() res: Response,
  ): Promise<void> {
    this.csrfService.assertValid(req);

    const values = {
      name: formString(req.body.name),
      email: formString(req.body.email),
      text: formString(req.body.text),
    };

    const errors: Record<string, string> = {};
    if (!values.name) {
      errors.name = 'El nombre es obligatorio';
    }
    if (!values.email) {
      errors.email = 'El email es obligatorio';
    } else if (!isEmail(values.email)) {
      errors.email = 'Introduce un email válido';
    }
    if (!values.text) {
      errors.text = 'El comentario es obligatorio';
    }

    const post = await this.blogService.findBySlug(slug);

    if (Object.keys(errors).length > 0) {
      await this.renderSinglePost(res, slug, post, values, errors);
      return;
    }

    if (!post) {
      await this.renderSinglePost(res, slug);
      return;
    }

    await this.blogService.addComment(post, values);
    req.session.flash = {
      type: 'success',
      message: 'Tu comentario se ha publicado.',
    };
    res.redirect(`/single_post/${encodeURIComponent(slug)}`);
  }

  @Get('single_post/:slug/like')
  likeFromBrowser(
    @Param('slug') slug: string,
    @Res() res: Response,
  ): Promise<void> {
    return this.like(slug, res);
  }

  @Post('single_post/:slug/like')
  likeFromAjax(
    @Param('slug') slug: string,
    @Res() res: Response,
  ): Promise<void> {
    return this.like(slug, res);
  }

  private async like(slug: string, res: Response): Promise<void> {
    const post = await this.blogService.like(slug);
    if (!post) {
      throw new NotFoundException('Post no encontrado');
    }
    res.json({ success: true, likes: post.numLikes });
  }

  private async renderBlogPage(res: Response, page: number): Promise<void> {
    const [{ posts, total, totalPages }, recents] = await Promise.all([
      this.blogService.listPosts(page, POSTS_PER_PAGE),
      this.blogService.findRecents(),
    ]);

    if (page > totalPages) {
      res.redirect(`/blog/${totalPages}`);
      return;
    }

    res.render('blog/index', {
      posts,
      recents,
      page,
      total,
      totalPages,
      searchTerm: null,
      pager: buildPager('/blog', page, totalPages),
    });
  }

  private async renderSinglePost(
    res: Response,
    slug: string,
    post?: Awaited<ReturnType<BlogService['findBySlug']>>,
    commentValues: Record<string, string> = {},
    commentErrors: Record<string, string> = {},
  ): Promise<void> {
    const [loadedPost, recents] = await Promise.all([
      post === undefined ? this.blogService.findBySlug(slug) : post,
      this.blogService.findRecents(),
    ]);

    res.render('blog/single_post', {
      post: loadedPost,
      recents,
      commentValues,
      commentErrors,
    });
  }
}

import {
  Controller,
  Get,
  Post,
  Req,
  Res,
} from '@nestjs/common';
import { Request, Response } from 'express';
import { AuthService } from './auth.service';
import { UsersService } from '../users/users.service';
import { CsrfService } from '../common/csrf.service';
import { formString, isEmail } from '../common/view-helpers';

@Controller()
export class AuthController {
  constructor(
    private readonly authService: AuthService,
    private readonly usersService: UsersService,
    private readonly csrfService: CsrfService,
  ) {}

  @Get('login')
  loginForm(@Req() req: Request, @Res() res: Response): void {
    const lastUsername = req.session.lastUsername ?? '';
    delete req.session.lastUsername;
    res.render('auth/login', { lastUsername });
  }

  @Post('login')
  async login(@Req() req: Request, @Res() res: Response): Promise<void> {
    this.csrfService.assertValid(req);

    const email = formString(req.body._username ?? req.body.email);
    const password =
      typeof req.body._password === 'string'
        ? req.body._password
        : formString(req.body.password);

    const user = await this.authService.validateCredentials(email, password);

    if (!user) {
      req.session.lastUsername = email;
      req.session.flash = {
        type: 'error',
        message: 'Invalid credentials.',
      };
      res.redirect('/login');
      return;
    }

    req.session.userId = user.id;
    req.session.flash = {
      type: 'success',
      message: `Bienvenido de nuevo, ${user.name}.`,
    };
    res.redirect('/');
  }

  @Get('logout')
  logout(@Req() req: Request, @Res() res: Response): void {
    req.session.destroy(() => {
      res.clearCookie('connect.sid');
      res.redirect('/');
    });
  }

  @Get('register')
  registerForm(@Res() res: Response): void {
    res.render('auth/register', {
      values: {},
      errors: {},
    });
  }

  @Post('register')
  async register(@Req() req: Request, @Res() res: Response): Promise<void> {
    this.csrfService.assertValid(req);

    const values = {
      email: formString(req.body.email),
      name: formString(req.body.name),
    };
    const password =
      typeof req.body.plainPassword === 'string'
        ? req.body.plainPassword
        : '';
    const agreeTerms = Boolean(req.body.agreeTerms);

    const errors: Record<string, string> = {};

    if (!values.email) {
      errors.email = 'Please enter your email';
    } else if (!isEmail(values.email)) {
      errors.email = `${values.email} is not a valid email`;
    } else if (await this.usersService.findByEmail(values.email)) {
      errors.email = 'There is already an account with this email';
    }

    if (!values.name) {
      errors.name = 'Please enter your name';
    }

    if (!password) {
      errors.plainPassword = 'Please enter a password';
    } else if (password.length < 6) {
      errors.plainPassword =
        'Your password should be at least 6 characters';
    }

    if (!agreeTerms) {
      errors.agreeTerms = 'You should agree to our terms.';
    }

    if (Object.keys(errors).length > 0) {
      res.render('auth/register', { values, errors });
      return;
    }

    const hashedPassword = await this.authService.hashPassword(password);
    const user = await this.usersService.create({
      email: values.email,
      name: values.name,
      password: hashedPassword,
      roles: [],
    });

    req.session.userId = user.id;
    req.session.flash = {
      type: 'success',
      message: 'Tu cuenta se ha creado correctamente.',
    };
    res.redirect('/');
  }
}

import {
  Controller,
  Get,
  Post,
  Req,
  Res,
  UploadedFile,
  UseGuards,
  UseInterceptors,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { copyFile } from 'fs/promises';
import { join } from 'path';
import { Request, Response } from 'express';
import { AdminService } from './admin.service';
import { AdminGuard } from '../common/guards';
import { CsrfService } from '../common/csrf.service';
import {
  GALLERY_IMAGE_DIR,
  PORTFOLIO_IMAGE_DIR,
} from '../common/paths';
import {
  imageStorage,
  isAllowedImageMime,
  removeUploadedFile,
} from '../common/upload';
import { formString, parseInteger } from '../common/view-helpers';

@Controller('admin')
@UseGuards(AdminGuard)
export class AdminController {
  constructor(
    private readonly adminService: AdminService,
    private readonly csrfService: CsrfService,
  ) {}

  @Get('categories')
  async categoriesForm(@Res() res: Response): Promise<void> {
    const categories = await this.adminService.listCategories();
    res.render('admin/categories', {
      categories,
      values: {},
      errors: {},
    });
  }

  @Post('categories')
  async createCategory(
    @Req() req: Request,
    @Res() res: Response,
  ): Promise<void> {
    this.csrfService.assertValid(req);

    const values = { name: formString(req.body.name) };
    const errors: Record<string, string> = {};

    if (!values.name) {
      errors.name = 'El nombre es obligatorio';
    }

    if (Object.keys(errors).length > 0) {
      const categories = await this.adminService.listCategories();
      res.render('admin/categories', { categories, values, errors });
      return;
    }

    await this.adminService.createCategory(values.name);
    req.session.flash = {
      type: 'success',
      message: 'Categoría creada correctamente.',
    };
    res.redirect('/admin/categories');
  }

  @Get('images')
  async imagesForm(@Res() res: Response): Promise<void> {
    await this.renderImages(res);
  }

  @Post('images')
  @UseInterceptors(
    FileInterceptor('file', {
      storage: imageStorage(GALLERY_IMAGE_DIR),
      limits: { fileSize: 5 * 1024 * 1024 },
    }),
  )
  async createImage(
    @Req() req: Request,
    @Res() res: Response,
    @UploadedFile() file?: Express.Multer.File,
  ): Promise<void> {
    try {
      this.csrfService.assertValid(req);
    } catch (error) {
      await removeUploadedFile(file);
      throw error;
    }

    const values = {
      numLikes: formString(req.body.numLikes),
      numViews: formString(req.body.numViews),
      numDownloads: formString(req.body.numDownloads),
      category: formString(req.body.category),
    };

    const errors: Record<string, string> = {};
    if (!file) {
      errors.file = 'La imagen es obligatoria';
    } else if (!isAllowedImageMime(file.mimetype)) {
      errors.file = 'Por favor sube una imagen válida (JPEG o PNG)';
    }

    const numLikes = parseInteger(values.numLikes, 0);
    const numViews = parseInteger(values.numViews, 0);
    const numDownloads = parseInteger(values.numDownloads, 0);

    if (Number.isNaN(numLikes)) {
      errors.numLikes = 'Introduce un número válido';
    }
    if (Number.isNaN(numViews)) {
      errors.numViews = 'Introduce un número válido';
    }
    if (Number.isNaN(numDownloads)) {
      errors.numDownloads = 'Introduce un número válido';
    }

    const categoryId = parseInteger(values.category, 0);
    const category =
      categoryId > 0
        ? await this.adminService.findCategoryById(categoryId)
        : null;
    if (!category) {
      errors.category = 'Selecciona una categoría';
    }

    if (Object.keys(errors).length > 0) {
      await removeUploadedFile(file);
      await this.renderImages(res, values, errors);
      return;
    }

    try {
      await copyFile(
        file.path,
        join(PORTFOLIO_IMAGE_DIR, file.filename),
      );
    } catch {
      await removeUploadedFile(file);
      await this.renderImages(res, values, {
        file: 'No se pudo copiar la imagen a la carpeta portfolio',
      });
      return;
    }

    await this.adminService.createImage({
      file: file.filename,
      numLikes,
      numViews,
      numDownloads,
      category,
    });

    req.session.flash = {
      type: 'success',
      message: 'Imagen subida correctamente.',
    };
    res.redirect('/admin/images');
  }

  private async renderImages(
    res: Response,
    values: Record<string, string> = {},
    errors: Record<string, string> = {},
  ): Promise<void> {
    const [images, categories] = await Promise.all([
      this.adminService.listImages(),
      this.adminService.listCategories(),
    ]);
    res.render('admin/images', { images, categories, values, errors });
  }
}

