        entities: ENTITIES,
        synchronize: true,
        charset: 'utf8mb4',
      }),
    }),
    TypeOrmModule.forFeature(ENTITIES),
  ],
  controllers: [
    PagesController,
    BlogController,
    AuthController,
    AdminController,
  ],
  providers: [
    UsersService,
    CsrfService,
    AuthService,
    BlogService,
    AdminService,
    ContactService,
    SeedService,
    AuthGuard,
    AdminGuard,
    AppViewMiddleware,
  ],
})
export class AppModule {}

import 'reflect-metadata';
import { NestFactory } from '@nestjs/core';
import { NestExpressApplication } from '@nestjs/platform-express';
import { ConfigService } from '@nestjs/config';
import session from 'express-session';
import * as nunjucks from 'nunjucks';
import { AppModule } from './app.module';
import { AppViewMiddleware } from './common/app-view.middleware';
import { CsrfService } from './common/csrf.service';
import { formatDate } from './common/date-format';
import { PUBLIC_DIR, VIEWS_DIR } from './common/paths';
import { asset } from './common/view-helpers';
import { UsersService } from './users/users.service';

async function bootstrap(): Promise<void> {
  const app = await NestFactory.create<NestExpressApplication>(AppModule);
  const config = app.get(ConfigService);

  const nunjucksEnvironment = nunjucks.configure(VIEWS_DIR, {
    express: app.getHttpAdapter().getInstance(),
    autoescape: true,
    noCache: config.get<string>('NODE_ENV') !== 'production',
    watch: config.get<string>('NODE_ENV') !== 'production',
    extensions: ['njk'],
  });
  nunjucksEnvironment.addFilter('date', formatDate);
  nunjucksEnvironment.addGlobal('asset', asset);
  app.setViewEngine('njk');

  // Archivos estáticos (CSS, JS, imágenes...)
  app.useStaticAssets(PUBLIC_DIR);

  app.use(
    session({
      secret: config.get<string>(
        'SESSION_SECRET',
        'nestjs-blog-secret-change-me',
      ),
      resave: false,
      saveUninitialized: false,
      cookie: {
        httpOnly: true,
        sameSite: 'lax',
        maxAge: 1000 * 60 * 60 * 8,
      },
    }),
  );

  // Carga el usuario de la sesión y variables comunes a todas las vistas.
  const viewer = new AppViewMiddleware(
    app.get(UsersService),
    app.get(CsrfService),
  );
  app.use((req, res, next) => viewer.use(req, res, next));

  const port = Number(config.get<string>('PORT', '3000'));
  await app.listen(port);
  // eslint-disable-next-line no-console
  console.log(`Blog NestJS escuchando en http://localhost:${port}`);
}

void bootstrap();

{% macro error(errors, field) -%}
  {%- if errors and errors[field] -%}
    <span class="help-block text-danger">{{ errors[field] }}</span>
  {%- endif -%}
{%- endmacro %}

{% if pager %}
  <nav class="pager" aria-label="Paginación de posts">
    <ul class="pagination">
      {% if pager.previousUrl %}
        <li class="pager-step">
          <a href="{{ pager.previousUrl }}" rel="prev" aria-label="Página anterior">
            <i class="fa fa-arrow-left"></i><span class="pager-label">Anterior</span>
          </a>
        </li>
      {% else %}
        <li class="pager-step disabled"><span aria-disabled="true">Anterior</span></li>
      {% endif %}

      {% for item in pager.pages %}
        {% if item.gap %}
          <li class="pager-gap" aria-hidden="true"><span>&hellip;</span></li>
        {% elif item.active %}
          <li class="active"><span aria-current="page">{{ item.label }}</span></li>
        {% else %}
          <li><a href="{{ item.url }}" aria-label="Página {{ item.label }}">{{ item.label }}</a></li>
        {% endif %}
      {% endfor %}

      {% if pager.nextUrl %}
        <li class="pager-step pager-next">
          <a href="{{ pager.nextUrl }}" rel="next" aria-label="Página siguiente">
            <span class="pager-label">Siguiente</span><i class="fa fa-arrow-right"></i>
          </a>
        </li>
      {% else %}
        <li class="pager-step pager-next disabled"><span aria-disabled="true">Siguiente</span></li>
      {% endif %}
    </ul>
    <p class="pager-status">{{ pager.status }}</p>
  </nav>
{% endif %}

