import session from 'express-session';
import { Repository } from 'typeorm';
import { Session } from '../entities/session.entity';

/**
 * Almacén de sesiones de express-session sobre TypeORM/MySQL.
 * Evita el MemoryStore, que pierde las sesiones al reiniciar y no escala.
 */
export class TypeOrmSessionStore extends session.Store {
  constructor(
    private readonly repository: Repository<Session>,
    private readonly ttlMs = 1000 * 60 * 60 * 8,
  ) {
    super();
  }

  get(
    sid: string,
    callback: (err: unknown, session?: session.SessionData | null) => void,
  ): void {
    this.repository
      .findOne({ where: { id: sid } })
      .then((row) => {
        if (!row) {
          callback(null, null);
          return;
        }
        if (row.expire.getTime() <= Date.now()) {
          void this.repository.delete(sid);
          callback(null, null);
          return;
        }
        try {
          callback(null, JSON.parse(row.sess) as session.SessionData);
        } catch {
          void this.repository.delete(sid);
          callback(null, null);
        }
      })
      .catch((error) => callback(error));
  }

  set(
    sid: string,
    value: session.SessionData,
    callback?: (err?: unknown) => void,
  ): void {
    const expires = value.cookie?.expires;
    const expire =
      expires instanceof Date
        ? expires
        : new Date(Date.now() + this.ttlMs);

    this.repository
      .save({ id: sid, sess: JSON.stringify(value), expire })
      .then(() => callback?.())
      .catch((error) => callback?.(error));
  }

  touch(
    sid: string,
    value: session.SessionData,
    callback?: (err?: unknown) => void,
  ): void {
    const expires = value.cookie?.expires;
    const expire =
      expires instanceof Date
        ? expires
        : new Date(Date.now() + this.ttlMs);

    this.repository
      .update({ id: sid }, { expire })
      .then(() => callback?.())
      .catch((error) => callback?.(error));
  }

  destroy(sid: string, callback?: (err?: unknown) => void): void {
    this.repository
      .delete({ id: sid })
      .then(() => callback?.())
      .catch((error) => callback?.(error));
  }

  /** Elimina sesiones caducadas; se puede invocar periódicamente. */
  async clearExpired(): Promise<void> {
    await this.repository
      .createQueryBuilder()
      .delete()
      .where('expire <= :now', { now: new Date() })
      .execute();
  }
}

import { NextFunction, Request, RequestHandler, Response } from 'express';

type Bucket = { count: number; resetAt: number };

const buckets = new Map<string, Bucket>();

export type RateLimitOptions = {
  windowMs: number;
  max: number;
  keyPrefix?: string;
  message?: string;
};

/**
 * Limitador de peticiones en memoria, suficiente para una instancia.
 * Para varias instancias habría que usar Redis.
 */
export function rateLimit(options: RateLimitOptions): RequestHandler {
  return (req: Request, res: Response, next: NextFunction): void => {
    const now = Date.now();
    const key = `${options.keyPrefix ?? req.path}:${req.ip}`;

    if (buckets.size > 5000) {
      for (const [bucketKey, bucket] of buckets) {
        if (bucket.resetAt <= now) {
          buckets.delete(bucketKey);
        }
      }
    }

    let bucket = buckets.get(key);
    if (!bucket || bucket.resetAt <= now) {
      bucket = { count: 0, resetAt: now + options.windowMs };
      buckets.set(key, bucket);
    }

    bucket.count += 1;

    res.setHeader('X-RateLimit-Limit', String(options.max));
    res.setHeader(
      'X-RateLimit-Remaining',
      String(Math.max(0, options.max - bucket.count)),
    );

    if (bucket.count > options.max) {
      const retryAfter = Math.ceil((bucket.resetAt - now) / 1000);
      res.setHeader('Retry-After', String(retryAfter));
      const message =
        options.message ??
        'Demasiadas peticiones. Espera unos minutos e inténtalo de nuevo.';

      if (req.accepts('html')) {
        res.status(429).render('errors/429', { message, retryAfter });
      } else {
        res.status(429).json({ statusCode: 429, message, retryAfter });
      }
      return;
    }

    next();
  };
}

/** Aplica un limitador solo a peticiones POST. */
export function onPost(handler: RequestHandler): RequestHandler {
  return (req, res, next) => {
    if (req.method !== 'POST') {
      next();
      return;
    }
    handler(req, res, next);
  };
}

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import nodemailer, { Transporter } from 'nodemailer';

/**
 * Envía correos si hay SMTP configurado. En desarrollo, si no hay SMTP,
 * escribe el mensaje en el log para poder probar el flujo completo.
 */
@Injectable()
export class MailService {
  private readonly logger = new Logger(MailService.name);
  private transporter: Transporter | null | undefined;

  constructor(private readonly config: ConfigService) {}

  private getTransporter(): Transporter | null {
    if (this.transporter !== undefined) {
      return this.transporter;
    }

    const host = this.config.get<string>('MAIL_HOST');
    if (!host) {
      this.transporter = null;
      return null;
    }

    this.transporter = nodemailer.createTransport({
      host,
      port: Number(this.config.get<string>('MAIL_PORT', '587')),
      secure: this.config.get<string>('MAIL_SECURE', 'false') === 'true',
      auth: this.config.get<string>('MAIL_USER')
        ? {
            user: this.config.get<string>('MAIL_USER'),
            pass: this.config.get<string>('MAIL_PASSWORD', ''),
          }
        : undefined,
    });

    return this.transporter;
  }

  async send(
    to: string,
    subject: string,
    text: string,
    html?: string,
  ): Promise<void> {
    const transporter = this.getTransporter();
    const from = this.config.get<string>(
      'MAIL_FROM',
      'NestJS Blog <no-reply@blog.local>',
    );

    if (!transporter) {
      this.logger.log(
        `[MAIL:desarrollo] Para: ${to} | Asunto: ${subject}\n${text}`,
      );
      return;
    }

    await transporter.sendMail({ from, to, subject, text, html }).catch((error) => {
      this.logger.error(`No se pudo enviar el correo a ${to}`, error);
    });
  }
}

/**
 * Validación mínima de variables de entorno al arrancar.
 * En desarrollo se permiten valores por defecto; en producción se exige
 * configuración explícita para no desplegar con secretos inseguros.
 */
export function validateEnv(
  config: Record<string, unknown>,
): Record<string, unknown> {
  const environment = String(config.NODE_ENV ?? 'development');

  if (environment !== 'production') {
    return config;
  }

  const required = [
    'DB_HOST',
    'DB_PORT',
    'DB_USERNAME',
    'DB_PASSWORD',
    'DB_DATABASE',
    'SESSION_SECRET',
  ];

  const missing = required.filter((key) => !config[key]);
  if (missing.length > 0) {
    throw new Error(
      `Faltan variables de entorno obligatorias en producción: ${missing.join(', ')}`,
    );
  }

  const secret = String(config.SESSION_SECRET);
  if (secret.length < 32 || secret.includes('cambia')) {
    throw new Error(
      'SESSION_SECRET debe tener al menos 32 caracteres y no ser el valor de ejemplo.',
    );
  }

  return config;
}

import {
  ArgumentsHost,
  Catch,
  ExceptionFilter,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { Request, Response } from 'express';

@Catch()
export class AllExceptionsFilter implements ExceptionFilter {
  private readonly logger = new Logger('Exceptions');

  catch(exception: unknown, host: ArgumentsHost): void {
    const context = host.switchToHttp();
    const response = context.getResponse<Response>();
    const request = context.getRequest<Request>();

    const status =
      exception instanceof HttpException
        ? exception.getStatus()
        : HttpStatus.INTERNAL_SERVER_ERROR;

    let message = 'Ha ocurrido un error interno. Inténtalo más tarde.';
    if (exception instanceof HttpException) {
      const payload = exception.getResponse();
      if (typeof payload === 'string') {
        message = payload;
      } else if (payload && typeof payload === 'object') {
        const raw = (payload as Record<string, unknown>).message;
        message = Array.isArray(raw) ? raw.join(', ') : String(raw ?? message);
      }
    }

    if (status >= 500) {
      this.logger.error(
        `${request.method} ${request.originalUrl} -> ${status}: ${message}`,
        exception instanceof Error ? exception.stack : undefined,
      );
    }

    if (response.headersSent) {
      return;
    }

    const wantsHtml =
      request.accepts('html') && !request.path.startsWith('/api');

    if (!wantsHtml) {
      response.status(status).json({ statusCode: status, message });
      return;
    }

    const view = status === 404 ? 'errors/404' : 'errors/error';
    response.status(status).render(view, {
      status,
      message:
        status === 404
          ? 'La página que buscas no existe o ha sido movida.'
          : message,
    });
  }
}

import { existsSync } from 'fs';
import { mkdir, rename } from 'fs/promises';
import { extname, join } from 'path';
import sharp from 'sharp';
import { GALLERY_IMAGE_DIR } from './paths';

/**
 * Reduce el tamaño de una imagen subida conservando su formato.
 * Si sharp falla, deja el archivo original intacto.
 */
export async function optimizeImage(filePath: string): Promise<void> {
  const extension = extname(filePath).toLowerCase();
  const temporary = `${filePath}.optimized`;

  try {
    const pipeline = sharp(filePath).rotate().resize({
      width: 1600,
      height: 1600,
      fit: 'inside',
      withoutEnlargement: true,
    });

    if (extension === '.png') {
      await pipeline.png({ compressionLevel: 8 }).toFile(temporary);
    } else {
      await pipeline.jpeg({ quality: 85, mozjpeg: true }).toFile(temporary);
    }

    await rename(temporary, filePath);
  } catch {
    // La imagen se conserva tal cual si no se puede procesar.
  }
}

/** Nombre del thumbnail asociado a un archivo de la galería. */
export function thumbnailName(file: string): string {
  const extension = extname(file);
  return `${file.slice(0, file.length - extension.length)}-thumb.jpg`;
}

/**
 * Genera un thumbnail junto a la imagen original de la galería.
 * Devuelve el nombre del thumbnail o null si no se pudo crear.
 */
export async function createThumbnail(file: string): Promise<string | null> {
  const source = join(GALLERY_IMAGE_DIR, file);
  if (!existsSync(source)) {
    return null;
  }

  const name = thumbnailName(file);
  try {
    await mkdir(GALLERY_IMAGE_DIR, { recursive: true });
    await sharp(source)
      .rotate()
      .resize({ width: 640, withoutEnlargement: true })
      .jpeg({ quality: 80 })
      .toFile(join(GALLERY_IMAGE_DIR, name));
    return name;
  } catch {
    return null;
  }
}

